const input = $input.first().json;
const body = input.body || {};
const patientId = String(body.patient_id || '').trim();
const appointmentId = String(body.appointment_id || '').trim();
const reason = String(body.reason || '').trim();

if (!patientId) {
  return [{ json: { __error: true, code: 403, message: 'patient_id is required' } }];
}

if (!appointmentId) {
  return [{ json: { __error: true, code: 400, message: 'appointment_id is required' } }];
}

return [{
  json: {
    patient_id: patientId,
    appointment_id: appointmentId,
    reason: reason
  }
}];

const loaded = $input.all().filter(r => r.json.id);
const input = $('Parse Cancel Appointment Input1').first().json;

if (loaded.length === 0) {
  return [{ json: { __error: true, code: 404, message: 'Cita no encontrada' } }];
}

const appt = loaded[0].json;

if (appt.patient_id !== input.patient_id) {
  return [{ json: { __error: true, code: 403, message: 'Esa cita no pertenece a este paciente' } }];
}

const status = String(appt.status || '').toLowerCase();
const TERMINAL = ['completed', 'cancelled', 'no_show', 'deleted'];
if (TERMINAL.includes(status)) {
  return [{ json: { __error: true, code: 409, message: `La cita ya está en estado '${status}' y no se puede cancelar` } }];
}

return [{ json: { ...input, from_status: status } }];

const input = $input.first().json;
const body = input.body || {};
const patientId = String(body.patient_id || '').trim();
const appointmentId = String(body.appointment_id || '').trim();
const desiredDate = String(body.desired_date || '').trim();
const desiredTime = String(body.desired_time || '').trim();

if (!patientId) {
  return [{ json: { __error: true, code: 403, message: 'patient_id is required' } }];
}

if (!appointmentId || !desiredDate || !desiredTime) {
  return [{ json: { __error: true, code: 400, message: 'appointment_id, desired_date and desired_time are required' } }];
}

return [{
  json: {
    patient_id: patientId,
    appointment_id: appointmentId,
    desired_date: desiredDate,
    desired_time: desiredTime
  }
}];

const loaded = $input.all().filter(r => r.json.id);
const input = $('Parse Update Appointment Input1').first().json;

if (loaded.length === 0) {
  return [{ json: { __error: true, code: 404, message: 'Cita no encontrada' } }];
}

const appt = loaded[0].json;

if (appt.patient_id !== input.patient_id) {
  return [{ json: { __error: true, code: 403, message: 'Esa cita no pertenece a este paciente' } }];
}

const status = String(appt.status || '').toLowerCase();
const TERMINAL = ['completed', 'cancelled', 'no_show', 'deleted'];
if (TERMINAL.includes(status)) {
  return [{ json: { __error: true, code: 409, message: `La cita ya está en estado '${status}' y no se puede reagendar` } }];
}

const durationMinutes = Math.round((new Date(appt.end_datetime).getTime() - new Date(appt.start_datetime).getTime()) / 60000) || 30;

return [{
  json: {
    ...input,
    from_status: status,
    original_assignee_id: appt.assignee_id,
    original_calendar_source_id: appt.calendar_source_id,
    duration_minutes: durationMinutes,
    summary: appt.summary,
    notes: appt.notes
  }
}];

const ctx = $('Validate Reschedule Eligibility1').first().json;
const sedeCalendars = $('Get Sede Calendars (Reschedule)1').first().json;
const testConfig = $input.first().json;
const isTestMode = !!testConfig.whatsapp_test_mode_enabled;
const calendarSourceIds = isTestMode
  ? String(testConfig.whatsapp_test_calendar_source_id || '')
  : (sedeCalendars.calendar_source_ids || '');

const start = new Date(`${ctx.desired_date}T${ctx.desired_time}:00`);
const end = new Date(start.getTime() + ctx.duration_minutes * 60000);

return [{
  json: {
    startingDateAndTime: start.toISOString().replace('Z', ''),
    endingDateAndTime: end.toISOString().replace('Z', ''),
    durationInMinutes: ctx.duration_minutes,
    mode: 'checkAvailability',
    calendarSourceIds,
    appointmentId: ctx.appointment_id,
    doctorId: ctx.original_assignee_id || '',
    patientId: ctx.patient_id
  }
}];

const ctx = $('Build Availability Request (Reschedule)1').first().json;
const result = $input.first().json;

const isAvailable = result?.isAvailable === true;

let chosen = null;
if (isAvailable) {
  const startIso = result.availableStartingTime;
  chosen = {
    assignee_id: result.availableDoctorId,
    assignee_name: result.availableDoctorName,
    calendar_source_id: result.availableCalendarSourceId,
    calendar_name: result.availableCalendarName,
    date: startIso ? startIso.slice(0, 10) : ctx.startingDateAndTime.slice(0, 10),
    time: startIso ? startIso.slice(11, 16) : ctx.startingDateAndTime.slice(11, 16)
  };
}

// Agent_Availability2 devuelve una fila por cada doctor disponible en ese horario (misma
// sede/consultorio ya fijados para el reagendamiento) -- el paciente no elige doctor acá,
// así que solo importa fecha+hora. Deduplicamos por esa clave y espaciamos los horarios
// (no ofrecer 09:00 y 09:20 como opciones "distintas") para no devolver decenas de filas
// casi idénticas.
const seen = new Set();
const slots = [];
for (const s of (result?.suggestedTimes || [])) {
  const key = `${s.fecha_cita}|${s.hora_cita}`;
  if (seen.has(key)) continue;
  seen.add(key);
  slots.push({ date: s.fecha_cita, time: s.hora_cita });
}

const toMinutes = (t) => { const [h, m] = t.split(':').map(Number); return h * 60 + m; };
slots.sort((a, b) => (a.date === b.date ? toMinutes(a.time) - toMinutes(b.time) : a.date.localeCompare(b.date)));

const grainMinutes = 60;
const MAX_SUGGESTIONS = 8;
const suggestions = [];
let lastKept = null;
for (const slot of slots) {
  if (suggestions.length >= MAX_SUGGESTIONS) break;
  const sameDayAsLast = lastKept && lastKept.date === slot.date;
  const gapOk = !sameDayAsLast || (toMinutes(slot.time) - toMinutes(lastKept.time)) >= grainMinutes;
  if (!gapOk) continue;
  suggestions.push(slot);
  lastKept = slot;
}

return [{ json: { isAvailable, chosen, suggestions } }];

const body = $input.first().json.body;
const patientId = String(body.patient_id || '').trim();
const dateFrom = String(body.date_from || '').trim();
const dateTo = String(body.date_to || '').trim();
return [{ json: { has_patient: !!patientId, patient_id: patientId, date_from: dateFrom || null, date_to: dateTo || null } }];

const summary = $('Get Account Summary1').all().map(i => i.json);
const quotes = $('Get Account Quotes1').all().map(i => i.json);
const detail = $('Get Account Detail1').all().map(i => i.json);

return [{
  json: {
    by_currency: summary,
    quotes,
    pending_invoices: detail
  }
}];

const body = $('POST wa-message-received').first().json.body || {};
const isInbound = body.type === 'whatsapp.inbound_message.received';

const msg = body.whatsappInboundMessage || body.whatsappMessage || {};
const textBody = msg.text?.body;
const wamid = msg.wamid || msg.id || '';
const fromPhone = msg.from || '';

const isTextMessage = isInbound && typeof textBody === 'string' && textBody.trim() !== '' && !!wamid && !!fromPhone;
const normalizedPhone = '+' + String(fromPhone || '').replace(/\D/g, '');

// Adjuntos (ordenes de estudio por WhatsApp): solo imagen y PDF, y solo si
// system_configurations.whatsapp_orders_enabled = true. Con el flag apagado todo
// lo que no es texto se ignora como siempre. Con el flag encendido, audio, video,
// stickers y otros formatos reciben una respuesta corta (ver 'Is Unsupported Media?').
const ordersEnabled = $('Get WhatsApp Agent Config').first().json.whatsapp_orders_enabled === true;
const msgType = String(msg.type || '');
const media = (msgType === 'image' || msgType === 'document') ? (msg[msgType] || null) : null;
const mime = String(media?.mime_type || '').toLowerCase().split(';')[0].trim();
const mimeOk = msgType === 'image'
  ? ['image/jpeg', 'image/png', 'image/webp'].includes(mime)
  : mime === 'application/pdf';
const isSupportedMedia = isInbound && !!media && !!media.link && mimeOk && !!wamid && !!fromPhone;
const FILE_TYPES = ['image', 'document', 'audio', 'video', 'sticker'];
const isUnsupportedMedia = isInbound && !isTextMessage && !isSupportedMedia && FILE_TYPES.includes(msgType) && !!wamid && !!fromPhone;

return [{
  json: {
    is_text_message: isTextMessage,
    is_unsupported_media: isUnsupportedMedia && ordersEnabled,
    is_processable: isTextMessage || (ordersEnabled && (isSupportedMedia || isUnsupportedMedia)),
    wamid,
    from_phone: normalizedPhone,
    // Un adjunto sin pie de foto deja el texto vacio (whatsapp_inbound_buffer.message_text es NOT NULL).
    message_text: textBody || media?.caption || '',
    media_kind: isSupportedMedia ? msgType : '',
    media_id: isSupportedMedia ? String(media.id || '') : '',
    media_url: isSupportedMedia ? String(media.link) : '',
    media_mime: isSupportedMedia ? mime : '',
    media_sha256: isSupportedMedia ? String(media.sha256 || '') : '',
    media_filename: isSupportedMedia ? String(media.filename || '') : '',
    media_caption: isSupportedMedia ? String(media.caption || '') : ''
  }
}];

