const extract = $('Combine Buffered Messages').first().json;
const patient = $('Resolve Patient Identity').first().json || {};
const intake = $input.first().json || {};
const cfg = $('Get WhatsApp Agent Config').first().json;

const isKnownPatient = !!patient.id;
const phoneAmbiguous = Number(patient.match_count || 0) > 1;
const ordersEnabled = cfg.whatsapp_orders_enabled === true;
const activeIntake = !!intake.intake_id;
const hasMedia = extract.has_media === true;

// A que agente va: al de ordenes si llego un archivo (ya extraido) o si ese telefono tiene una
// orden en curso. Con el flag apagado siempre va al general.
const route = ordersEnabled && (hasMedia || activeIntake) ? 'orders' : 'general';

return [{
  json: {
    patient_id: patient.id || null,
    patient_name: patient.name || '',
    is_known_patient: isKnownPatient,
    phone_ambiguous: phoneAmbiguous,
    orders_enabled: ordersEnabled,
    route,
    intake_status: intake.status || null,
    phone: extract.from_phone,
    message_text: extract.message_text || (hasMedia ? '[El usuario envió su orden de estudio como archivo]' : '')
  },
  pairedItem: { item: 0 }
}];

// Ventana de atención del agente de WhatsApp.
// Lee system_configurations.whatsapp_agent_business_hours (JSON):
//   { enabled, timezone,
//     rules: [ { days: ["mon".."sun"], ranges: [["HH:MM","HH:MM"], ...] }, ... ],
//     holidays?: ["YYYY-MM-DD"], off_hours_reply? }
// Compat: si viene "schedule" { mon..sun: [...] } y no "rules", se usa ese formato viejo.
// Ventanas efectivas del día = unión de los ranges de toda regla que incluya ese día.
// Cada rango = ventana en la que el agente SÍ responde (hora local, fin exclusivo; "24:00" = fin del día).
// Fail-open: sin config / enabled=false / JSON inválido => el agente responde siempre.
const cfg = $('Get WhatsApp Agent Config').first().json;
let bh;
try { bh = JSON.parse(cfg.whatsapp_agent_business_hours || '{}'); } catch (e) { bh = {}; }

if (!bh || bh.enabled === false || (!Array.isArray(bh.rules) && !bh.schedule)) {
  return [{ json: { ...($input.first()?.json || {}), within_agent_hours: true, agent_hours_debug: { reason: 'no_config' } } }];
}

const TZ = bh.timezone || 'America/Montevideo';
const P = (opts) => new Intl.DateTimeFormat('en-CA', { timeZone: TZ, ...opts })
  .formatToParts(new Date()).reduce((a, x) => (a[x.type] = x.value, a), {});
const p = P({ weekday: 'short', hour: '2-digit', minute: '2-digit', hour12: false });
const d = P({ year: 'numeric', month: '2-digit', day: '2-digit' });
const yyyymmdd = `${d.year}-${d.month}-${d.day}`;

const dayKey = p.weekday.toLowerCase().slice(0, 3);
let hh = parseInt(p.hour, 10);
if (hh === 24) hh = 0;
const mins = hh * 60 + parseInt(p.minute, 10);
const toMin = (t) => { const [h, m] = String(t).split(':').map(Number); return h * 60 + m; };

const isHoliday = Array.isArray(bh.holidays) && bh.holidays.includes(yyyymmdd);
let windows = [];
if (!isHoliday) {
  if (Array.isArray(bh.rules)) {
    windows = bh.rules
      .filter((r) => r && Array.isArray(r.days) && r.days.includes(dayKey))
      .flatMap((r) => (Array.isArray(r.ranges) ? r.ranges : []));
  } else if (bh.schedule) {
    windows = bh.schedule[dayKey] || [];
  }
}
const within = windows.some(([s, e]) => {
  const a = toMin(s), b = toMin(e);
  return a <= b ? (mins >= a && mins < b) : (mins >= a || mins < b);
});

return [{
  json: {
    ...($input.first()?.json || {}),
    within_agent_hours: within,
    agent_hours_debug: { tz: TZ, day: dayKey, local_time: `${String(hh).padStart(2, '0')}:${p.minute}`, is_holiday: isHoliday },
  },
}];

const input = $input.first().json;
const body = input.body || {};
const patientId = String(body.patient_id || '').trim();
const desiredDate = String(body.desired_date || '').trim();
const desiredTime = String(body.desired_time || '').trim();
const sedeId = String(body.sede_id || '').trim();

if (!patientId) {
  return [{ json: { __error: true, code: 403, message: 'patient_id is required' } }];
}

if (!desiredDate) {
  return [{ json: { __error: true, code: 400, message: 'desired_date is required' } }];
}

return [{
  json: {
    patient_id: patientId,
    preferred_doctor_name: body.preferred_doctor_name || '',
    desired_date: desiredDate,
    desired_time: desiredTime,
    sede_id: sedeId
  }
}];

const ctx = $('Resolve Service & Window').first().json;
const service = $('Find Service').first().json;
const preferredDoctor = $('Find Preferred Doctor').first().json;
const sedeCalendars = $('Get Sede Calendars').first().json;
const testConfig = $input.first().json;
const isTestMode = !!testConfig.whatsapp_test_mode_enabled;
const calendarSourceIds = isTestMode
  ? String(testConfig.whatsapp_test_calendar_source_id || '')
  : (sedeCalendars.calendar_source_ids || '');
const rawMap = sedeCalendars.calendar_sede_map || [];
const mapRows = typeof rawMap === 'string' ? JSON.parse(rawMap) : rawMap;
const sedeByCalendar = {};
(mapRows || []).forEach((r) => { sedeByCalendar[String(r.calendar_source_id)] = { sede_id: r.sede_id, sede_name: r.sede_name, sede_address: r.sede_address }; });

const durationMinutes = Number(service?.duration_minutes) || 30;
const hasDesiredTime = Boolean(ctx.desired_time);
const mode = hasDesiredTime ? 'checkAvailability' : 'listAvailability';
const start = hasDesiredTime
  ? new Date(`${ctx.desired_date}T${ctx.desired_time}:00`)
  : new Date(`${ctx.desired_date}T00:00:00`);
const end = new Date(start.getTime() + (hasDesiredTime ? durationMinutes : 24 * 60) * 60000);

return [{
  json: {
    startingDateAndTime: start.toISOString().replace('Z', ''),
    endingDateAndTime: end.toISOString().replace('Z', ''),
    durationInMinutes: durationMinutes,
    mode,
    calendarSourceIds,
    appointmentId: '',
    doctorId: preferredDoctor.id || '',
    patientId: ctx.patient_id,
    service,
    sedeByCalendar
  }
}];

// Réplica local de la lógica "Get_possible_schedules" de Agent_Availability2 (rama sin
// disponibilidad puntual). No se modifica el sub-workflow compartido -- su contrato
// público (mode='checkAvailability') es usado también por el frontend, así que este
// escaneo de día completo se implementa acá, en el flujo del agente, antes de responder
// la tool.
const calendars = ($input.first().json.calendars || [])
  .filter(c => c && c.id != null);

const doctorSlots = ($input.first().json.available_doctors || []);

const allAppointments = ($input.first().json.appointments || [])
  .filter(a => a && a.id != null);

const req = $('Build Availability Request').first().json;
const startTimeString = req.startingDateAndTime;
const endTimeString = req.endingDateAndTime;
const durationMinutes = parseInt(req.durationInMinutes) || 60;

const localTimezone = 'America/Montevideo';
const startTime = DateTime.fromISO(startTimeString, { zone: localTimezone }).toJSDate();
const endTime = DateTime.fromISO(endTimeString, { zone: localTimezone }).toJSDate();
const intervalMinutes = durationMinutes;

const possibleAppointments = [];
let currentTime = new Date(startTime);

while (currentTime < endTime) {
  const slotEndTime = new Date(currentTime.getTime() + intervalMinutes * 60000);
  const currentLuxonTime = DateTime.fromJSDate(currentTime);

  const doctorSlot = doctorSlots.find(slot => {
    const slotLuxonTime = DateTime.fromISO(slot.local_hour_tz);
    return slotLuxonTime.equals(currentLuxonTime);
  });

  let dbAvailableDoctors = [];
  if (doctorSlot && doctorSlot.ids_disponibles && doctorSlot.ids_disponibles.length > 0) {
    dbAvailableDoctors = doctorSlot.ids_disponibles;
  } else {
    currentTime.setMinutes(currentTime.getMinutes() + intervalMinutes);
    continue;
  }

  const trulyAvailableDoctors = dbAvailableDoctors.filter(doctor => {
    const isBusy = allAppointments.some(appt => {
      const apptStart = new Date(appt.start_datetime);
      const apptEnd = new Date(appt.end_datetime);
      const overlaps = apptStart < slotEndTime && apptEnd > currentTime;
      if (!overlaps) return false;
      return appt.assignee_id === doctor.user_id;
    });
    return !isBusy;
  });

  if (trulyAvailableDoctors.length === 0) {
    currentTime.setMinutes(currentTime.getMinutes() + intervalMinutes);
    continue;
  }

  for (const calendar of calendars) {
    const calendarSourceId = Number(calendar.id);
    const calendarName = calendar.name;
    const googleCalendarId = calendar.google_calendar_id;

    const isCalendarBusy = allAppointments.some(appt => {
      if (Number(appt.calendar_source_id) !== calendarSourceId) return false;
      const apptStart = new Date(appt.start_datetime);
      const apptEnd = new Date(appt.end_datetime);
      return apptStart < slotEndTime && apptEnd > currentTime;
    });

    if (!isCalendarBusy) {
      for (const doctor of trulyAvailableDoctors) {
        possibleAppointments.push({
          calendar_source_id: calendarSourceId,
          calendar_name: calendarName,
          google_calendar_id: googleCalendarId,
          fecha_cita: currentTime.toLocaleDateString('sv-SE'),
          hora_cita: currentTime.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit', timeZone: localTimezone }),
          start_datetime: currentTime.toISOString(),
          end_datetime: slotEndTime.toISOString(),
          user_id: doctor.user_id,
          user_name: doctor.user_name
        });
      }
    }
  }

  currentTime.setMinutes(currentTime.getMinutes() + intervalMinutes);
}

return possibleAppointments.map(appt => ({ json: appt }));

const request = $('Build Availability Request').first().json;
const service = request.service;
const sedeByCalendar = request.sedeByCalendar || {};
const result = $input.first().json;

const isAvailable = result?.isAvailable === true;

let chosen = null;
if (isAvailable) {
  const startIso = result.availableStartingTime;
  const sede = sedeByCalendar[String(result.availableCalendarSourceId)] || {};
  chosen = {
    assignee_id: result.availableDoctorId,
    assignee_name: result.availableDoctorName,
    calendar_source_id: result.availableCalendarSourceId,
    calendar_name: result.availableCalendarName,
    sede_id: sede.sede_id,
    sede_name: sede.sede_name,
    sede_address: sede.sede_address,
    date: startIso ? startIso.slice(0, 10) : request.startingDateAndTime.slice(0, 10),
    time: startIso ? startIso.slice(11, 16) : request.startingDateAndTime.slice(11, 16)
  };
}

// Agent_Availability2 devuelve una fila por cada combinación doctor x consultorio que
// coincide en una sede+horario -- el paciente no elige doctor/consultorio en este paso
// (eso lo resuelve automáticamente el próximo check_availability con desired_time puesto),
// así que acá solo importa fecha+hora+sede. Deduplicamos por esa clave y espaciamos los
// horarios (no ofrecer 09:00 y 09:20 como opciones "distintas") con un tope por sede, para
// no devolver cientos de filas casi idénticas cuando se pide disponibilidad de todo un día.
const seen = new Set();
const bySede = new Map();
for (const s of (result?.suggestedTimes || [])) {
  const sede = sedeByCalendar[String(s.calendar_source_id)] || {};
  const sedeId = sede.sede_id || 'unknown';
  const key = `${s.fecha_cita}|${s.hora_cita}|${sedeId}`;
  if (seen.has(key)) continue;
  seen.add(key);
  if (!bySede.has(sedeId)) bySede.set(sedeId, { sede_name: sede.sede_name, sede_address: sede.sede_address, slots: [] });
  bySede.get(sedeId).slots.push({ date: s.fecha_cita, time: s.hora_cita });
}

const toMinutes = (t) => { const [h, m] = t.split(':').map(Number); return h * 60 + m; };
const durationMinutes = Number(service?.duration_minutes) || 30;
const grainMinutes = Math.max(60, durationMinutes);
const MAX_PER_SEDE = 6;

const suggestions = [];
for (const [sedeId, data] of bySede) {
  data.slots.sort((a, b) => (a.date === b.date ? toMinutes(a.time) - toMinutes(b.time) : a.date.localeCompare(b.date)));
  let lastKept = null;
  let keptForSede = 0;
  for (const slot of data.slots) {
    if (keptForSede >= MAX_PER_SEDE) break;
    const sameDayAsLast = lastKept && lastKept.date === slot.date;
    const gapOk = !sameDayAsLast || (toMinutes(slot.time) - toMinutes(lastKept.time)) >= grainMinutes;
    if (!gapOk) continue;
    suggestions.push({ sede_id: sedeId, sede_name: data.sede_name, sede_address: data.sede_address, date: slot.date, time: slot.time });
    lastKept = slot;
    keptForSede += 1;
  }
}

return [{ json: {
  service: { name: service?.name, duration_minutes: service?.duration_minutes, price: service?.price, currency: service?.currency },
  isAvailable,
  chosen,
  suggestions
} }];

