  .filter(r => r.media_kind && r.media_url)
  .map(r => ({
    wamid: r.wamid,
    kind: r.media_kind,
    id: r.media_id || '',
    url: r.media_url,
    mime: r.media_mime || '',
    sha256: r.media_sha256 || '',
    filename: r.media_filename || '',
    caption: r.media_caption || ''
  }));

if (parts.length === 0 && allMedia.length === 0) {
  return [];
}

