return [{
  json: {
    from_phone: extract.from_phone,
    wamid: extract.wamid,
    message_text: parts.join(String.fromCharCode(10)),
    batch_size: rows.length,
    has_media: allMedia.length > 0,
    media: allMedia.slice(0, MAX_FILES),
