  && msg.type === 'text'
  && typeof msg.text?.body === 'string'
  && msg.text.body.trim() !== ''
  && !!msg.to;

const phone = '+' + String(msg.to || '').replace(/\D/g, '');

return [{
  json: {
    is_text_echo: isTextEcho,
    phone,
    message_text: msg.text?.body || ''
  }
}];

